"use strict";document.addEventListener("DOMContentLoaded",function(){const e=Array.from(document.querySelectorAll("[data-video-seek]"),e=>({button:e,start:parseFloat(e.dataset.videoSeek)}));if(0===e.length)return;const t=document.querySelector("[data-video-watch-player] video");let n=null;const r=()=>{const r=e.filter(e=>e.start<=t.currentTime),o=r.length>0?r[r.length-1].button:null;o!==n&&(n?.removeAttribute("aria-current"),o?.setAttribute("aria-current","true"),n=o)};document.addEventListener("click",e=>{const n=e.target.closest("[data-video-seek]");if(!n)return;t.currentTime=parseFloat(n.dataset.videoSeek),t.play();const r=t.getBoundingClientRect();(r.top<0||r.bottom>window.innerHeight)&&t.scrollIntoView({behavior:"smooth",block:"center"})}),t.addEventListener("timeupdate",r),t.addEventListener("seeked",r)});